files.content:
:root {
  --bg: #1e1b2e;
  --card: #2d2a3e;
  --text: #f0edf7;
  --muted: #a89fc0;
  --accent: #7c5cbf;
  --accent-hover: #9478d4;
  --accent-pressed: #5e3f9e;
  --available: #4caf7a;
  --checked: #c45c5c;
  --border: #4a4560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 540px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 20px;
  text-align: center;
  color: var(--text);
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}

.filter-label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 1rem;
  color: var(--muted);
  user-select: none;
}

.filter-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}

.filter-label input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--accent-hover);
  outline-offset: 2px;
}

.count {
  font-size: 1rem;
  font-weight: 600;
  color: var(--accent-hover);
}

.book-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.book-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 16px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 10px;
}

.book-title {
  font-size: 1rem;
  font-weight: 500;
  flex: 1 1 140px;
}

.book-status {
  font-size: 0.85rem;
  font-weight: 600;
  padding: 2px 10px;
  border-radius: 999px;
  white-space: nowrap;
}

.book-status.available {
  background: rgba(76, 175, 122, 0.15);
  color: var(--available);
}

.book-status.checked {
  background: rgba(196, 92, 92, 0.15);
  color: var(--checked);
}

button {
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 8px 16px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  white-space: nowrap;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
}

button:focus-visible {
  outline: 2px solid var(--accent-hover);
  outline-offset: 2px;
}

.empty-state {
  text-align: center;
  color: var(--muted);
  padding: 24px 0;
  font-size: 1rem;
}

@media (max-width: 400px) {
  .app-card {
    padding: 16px;
  }

  .book-item {
    flex-direction: column;
    align-items: flex-start;
  }

  button {
    width: 100%;
    text-align: center;
  }
}

const books = [
  { id: 1, title: 'The Pixel Frontier', checkedOut: false },
  { id: 2, title: 'Realm of Pixels', checkedOut: true },
  { id: 3, title: 'Digital Canvas', checkedOut: false },
  { id: 4, title: 'Chromatic Dreams', checkedOut: false },
  { id: 5, title: 'Bit by Bit', checkedOut: true },
  { id: 6, title: 'The Render Engine', checkedOut: false },
];

const bookList = document.getElementById('bookList');
const checkedOutCount = document.getElementById('checkedOutCount');
const availableFilter = document.getElementById('availableFilter');
const emptyState = document.getElementById('emptyState');

function render() {
  bookList.innerHTML = '';

  const filterActive = availableFilter.checked;
  let visibleCount = 0;

  books.forEach((book) => {
    const li = document.createElement('li');
    li.className = 'book-item';

    const title = document.createElement('span');
    title.className = 'book-title';
    title.textContent = book.title;

    const status = document.createElement('span');
    status.className = 'book-status ' + (book.checkedOut ? 'checked' : 'available');
    status.textContent = book.checkedOut ? 'Checked out' : 'Available';

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = book.checkedOut ? 'Return' : 'Check out';
    btn.setAttribute('aria-label', (book.checkedOut ? 'Return ' : 'Check out ') + book.title);
    btn.addEventListener('click', () => {
      book.checkedOut = !book.checkedOut;
      render();
    });

    li.append(title, status, btn);

    if (filterActive && book.checkedOut) {
      li.hidden = true;
    } else {
      visibleCount++;
    }

    bookList.appendChild(li);
  });

  emptyState.hidden = visibleCount > 0;

  const count = books.filter((b) => b.checkedOut).length;
  checkedOutCount.textContent = 'Checked out: ' + count;
}

availableFilter.addEventListener('change', render);

render();
